 "content": "def transform(grid):
    """Complete horizontal rail gaps and their matching vertical color runs."""
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])

    # The sparse vertical endpoint marks at the bottom identify the rail columns.
    rail_cols = {c for r in range(max(0, h - 2), h) for c, v in enumerate(grid[r]) if v != 0}
    for c in sorted(rail_cols):
        if c == 0 or c == w - 1:
            continue
        anchors = []
        for r in range(h):
            color = grid[r][c - 1]
            if (grid[r][c] == 0 and color != 0 and grid[r][c + 1] == color):
                anchors.append((r, color))
        if not anchors:
            continue
        # Each rail row closes its one-cell horizontal gap. The color at that
        # rail fills the vertical interval above it, stopping at the previous rail.
        previous = -1
        for r, color in anchors:
            out[r][c] = color
            for rr in range(previous + 1, r):
                out[rr][c] = color
            previous = r
    return out

