                out[r][c] = color

    # Extend each marked rail vertically. Horizontal gap cells and any existing
    # vertical pixels are color anchors; blank cells take the nearest anchor's
    # color, with ties resolved toward the lower (later) anchor.
    for c, row_gaps in gaps.items():
        anchors = dict(row_gaps)
        for r in range(h):
            if grid[r][c] != 0:
                anchors[r] = grid[r][c]
        positions = sorted(anchors)
        for r in range(h):
            if out[r][c] != 0:
                continue
            nearest = min(positions, key=lambda ar: (abs(ar - r), -ar))
            out[r][c] = anchors[nearest]
    return out

