    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0

    # A one-cell horizontal interruption is a crossing anchor for a vertical
    # color rail. Restore all such horizontal cells first.
    gaps = {}
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                gaps.setdefault(c, []).append((r, color))
                out[r][c] = color

    # The vertical colored tail is the bottom anchor. Horizontal crossings
    # divide the column into bands: the top band uses its own crossing color,
    # and each subsequent band uses the color of its lower crossing.
    for c, crossings in gaps.items():
        crossings.sort()
        seed_rows = [r for r in range(h) if grid[r][c] != 0]
        seed_start = None
        seed_color = None
        if seed_rows:
            last = seed_rows[-1]
            seed_color = grid[last][c]
            seed_start = last
            while seed_start > 0 and grid[seed_start - 1][c] == seed_color:
                seed_start -= 1

        anchors = crossings[:]
        if seed_start is not None:
            anchors.append((seed_start, seed_color))
        anchors.sort()

        first_r, first_color = anchors[0]
        for r in range(first_r):
            out[r][c] = first_color
        for (upper_r, _), (lower_r, lower_color) in zip(anchors, anchors[1:]):
            for r in range(upper_r + 1, lower_r):
                out[r][c] = lower_color
    return out

